var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
builder.Services.AddHttpClient("api")
    .ConfigureHttpMessageHandlerBuilder(b =>
    {
        ((HttpClientHandler)b.PrimaryHandler).UseCookies = false;
    });
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

arguments.new_str:
using Microsoft.AspNetCore.HttpOverrides;
using System.Net.Http;

// Placeholder service interfaces/types for demonstration
public interface IUserService { }
public class UserService : IUserService { }
public interface ICacheService { }
public class CacheService : ICacheService
{
    public CacheService(IUserService userService) { }
}

var builder = WebApplication.CreateBuilder(args);

// Breaking change fix: ValidateOnBuild is now enabled by default in Development.
// A scoped service (IUserService) captured inside a singleton (CacheService) violates
// scope validation. Fix: register CacheService as scoped instead of singleton.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Breaking change fix: HttpClientFactory now uses SocketsHttpHandler by default.
// Casting to HttpClientHandler throws InvalidCastException at runtime.
// Fix: use ConfigurePrimaryHttpMessageHandler to set the handler explicitly.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Breaking change fix: ForwardedHeadersMiddleware now ignores X-Forwarded-* headers
// from proxies not in KnownProxies/KnownNetworks. Configure your trusted proxy.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // Add your reverse proxy address(es) here:
    options.KnownProxies.Add(System.Net.IPAddress.Loopback);
});

// Breaking change fix: HttpClientFactory Trace-level logs now redact all header values
// by default. Allowlist specific non-sensitive headers you need for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(header =>
        header == "Authorization" || header == "Cookie" || header == "Set-Cookie"));

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

