1. using Microsoft.AspNetCore.HttpOverrides;
2. 
3. var builder = WebApplication.CreateBuilder(args);
4. 
5. // Breaking change fix: ValidateOnBuild is now enabled by default in Development.
6. // A scoped service (IUserService) captured inside a singleton (CacheService) violates
7. // scope validation. Fix: register CacheService as scoped instead of singleton.
8. builder.Services.AddScoped<IUserService, UserService>();
9. builder.Services.AddScoped<ICacheService>(sp =>
10.     new CacheService(sp.GetRequiredService<IUserService>()));
11. 
12. // Breaking change fix: HttpClientFactory now uses SocketsHttpHandler by default.
13. // Casting to HttpClientHandler throws InvalidCastException at runtime.
14. // Fix: use ConfigurePrimaryHttpMessageHandler to set the handler explicitly.
15. builder.Services.AddHttpClient("api")
16.     .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });
17. 
18. // Breaking change fix: ForwardedHeadersMiddleware now ignores X-Forwarded-* headers
19. // from proxies not in KnownProxies/KnownNetworks. Configure your trusted proxy.
20. builder.Services.Configure<ForwardedHeadersOptions>(options =>
21. {
22.     options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
23.     // Add your reverse proxy address(es) here:
24.     options.KnownProxies.Add(System.Net.IPAddress.Loopback);
25. });
26. 
27. // Breaking change fix: HttpClientFactory Trace-level logs now redact all header values
28. // by default. Allowlist specific non-sensitive headers you need for debugging.
29. builder.Services.ConfigureHttpClientDefaults(b =>
30.     b.RedactLoggedHeaders(header =>
31.         header == "Authorization" || header == "Cookie" || header == "Set-Cookie"));
32. 
33. var app = builder.Build();
34. app.UseForwardedHeaders();
35. app.Run();
36. 
